#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "Unknown top-level member is rejected.",
                "{\n  \"__x__\": true,\n  \"id\": \"6f9619ff-8b86-d011-b42d-00cf4fc964ff\"\n}",
            ),
            ("`id` is required.", "{}"),
            (
                "`pop.type` must be the literal `VrcRevokeAuthorization` — a `VrcPublishAuthorization` (vtc/relationships/publish's authorization) cannot be replayed here.",
                "{\n  \"id\": \"6f9619ff-8b86-d011-b42d-00cf4fc964ff\",\n  \"pop\": {\n    \"documentId\": \"urn:uuid:7d9f1b3d-5e7a-4c9b-8d1f-3a5c7e9b1d01\",\n    \"proof\": {},\n    \"relationship\": \"6f9619ff-8b86-d011-b42d-00cf4fc964ff\",\n    \"type\": \"VrcPublishAuthorization\"\n  }\n}",
            ),
            (
                "`pop` without `proof` carries no evidence of control.",
                "{\n  \"id\": \"6f9619ff-8b86-d011-b42d-00cf4fc964ff\",\n  \"pop\": {\n    \"documentId\": \"urn:uuid:7d9f1b3d-5e7a-4c9b-8d1f-3a5c7e9b1d01\",\n    \"relationship\": \"6f9619ff-8b86-d011-b42d-00cf4fc964ff\",\n    \"type\": \"VrcRevokeAuthorization\"\n  }\n}",
            ),
            (
                "`pop` without `relationship` does not bind the authorization to an edge.",
                "{\n  \"id\": \"6f9619ff-8b86-d011-b42d-00cf4fc964ff\",\n  \"pop\": {\n    \"documentId\": \"urn:uuid:7d9f1b3d-5e7a-4c9b-8d1f-3a5c7e9b1d01\",\n    \"proof\": {},\n    \"type\": \"VrcRevokeAuthorization\"\n  }\n}",
            ),
            (
                "`pop` without `documentId` does not bind the authorization to this request.",
                "{\n  \"id\": \"6f9619ff-8b86-d011-b42d-00cf4fc964ff\",\n  \"pop\": {\n    \"proof\": {},\n    \"relationship\": \"6f9619ff-8b86-d011-b42d-00cf4fc964ff\",\n    \"type\": \"VrcRevokeAuthorization\"\n  }\n}",
            ),
            (
                "Unknown member inside `pop` is rejected.",
                "{\n  \"id\": \"6f9619ff-8b86-d011-b42d-00cf4fc964ff\",\n  \"pop\": {\n    \"__x__\": true,\n    \"documentId\": \"urn:uuid:7d9f1b3d-5e7a-4c9b-8d1f-3a5c7e9b1d01\",\n    \"proof\": {},\n    \"relationship\": \"6f9619ff-8b86-d011-b42d-00cf4fc964ff\",\n    \"type\": \"VrcRevokeAuthorization\"\n  }\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
}
